func TestGettersListCalendarResponse(t *testing.T) {
	t.Run("GetRows", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &ListCalendarResponse{}
		var expected []*ListCalendarResponseRowsItem
		obj.Rows = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetRows(), "getter should return the property value")
	})

	t.Run("GetRows_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &ListCalendarResponse{}
		obj.Rows = nil

		// Act & Assert
		assert.Nil(t, obj.GetRows(), "getter should return nil when property is nil")
	})

	t.Run("GetRows_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *ListCalendarResponse
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetRows() // Should return zero value
	})

}

